package com.jnapanam.sportszone.training.controller;import com.jnapanam.sportszone.training.dto.*;import com.jnapanam.sportszone.training.service.TrainingService;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/public/training")public class PublicTrainingController{private final TrainingService s;private final com.jnapanam.sportszone.features.FeaturePolicyService policy;public PublicTrainingController(TrainingService s,com.jnapanam.sportszone.features.FeaturePolicyService policy){this.s=s;this.policy=policy;}@GetMapping("/programs")public List<ProgramResponse>programs(){return policy.visibleFor("TRAINING","CUSTOMER")?s.publicPrograms():List.of();}@GetMapping("/batches")public List<BatchResponse>batches(){return policy.visibleFor("TRAINING","CUSTOMER")?s.publicBatches():List.of();}}
